it('should render star at correct position based on angle and distance', () => {
  const { container } = render(
    <Star x={100} y={100} angle={Math.PI / 2} delay={0} seed="test-1" />
  );
  const star = container.querySelector('div');
  expect(star).toHaveStyle({ position: 'absolute' });
  expect(star?.querySelector('svg')).toBeInTheDocument();
});

it('should not render star when frame is before start time plus delay', () => {
  mockUseCurrentFrame.mockReturnValue(40);
  const { container } = render(
    <Star x={100} y={100} angle={0} delay={10} seed="test" />
  );
  expect(container.firstChild).toBeNull();
});

it('should assign star color from valid color palette', () => {
  const validColors = ['#FFD700', '#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE'];
  const { container } = render(
    <Star x={100} y={100} angle={0} delay={0} seed="test-color" />
  );
  const path = container.querySelector('path');
  const fillColor = path?.getAttribute('fill');
  expect(validColors).toContain(fillColor);
});

it('should shake bell when shaking is true and frame is in shake range', () => {
  mockUseCurrentFrame.mockReturnValue(60);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<BellIcon shaking={true} />);
  const svg = container.querySelector('svg');
  const transform = svg?.style.transform;
  expect(transform).toMatch(/rotate\(-?\d+\.?\d*deg\)/);
  expect(transform).not.toBe('rotate(0deg)');
});

it('should not shake bell when shaking is false', () => {
  mockUseCurrentFrame.mockReturnValue(60);
  const { container } = render(<BellIcon shaking={false} />);
  const svg = container.querySelector('svg');
  expect(svg?.style.transform).toBe('rotate(0deg)');
});

it('should render arrow cursor SVG', () => {
  const { container } = render(<ArrowCursor />);
  const svg = container.querySelector('svg');
  expect(svg).toBeInTheDocument();
  expect(svg?.querySelector('path')).toHaveAttribute('fill', 'white');
});

it('should render hand cursor SVG', () => {
  const { container } = render(<HandCursor />);
  const svg = container.querySelector('svg');
  expect(svg).toBeInTheDocument();
  expect(svg).toHaveAttribute('width', '118');
  expect(svg).toHaveAttribute('height', '118');
});

it('should scale button down and back up on click', () => {
  mockUseCurrentFrame.mockReturnValue(45);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<SubscribeButton clicked={true} />);
  const button = container.querySelector('div');
  const transform = button?.style.transform;
  expect(transform).toMatch(/scale\(0\.95\)/);
});

it('should change background from red to gray when clicked', () => {
  const { rerender, container } = render(<SubscribeButton clicked={false} />);
  let button = container.querySelector('div');
  expect(button).toHaveStyle({ backgroundColor: '#FF0000' });

  rerender(<SubscribeButton clicked={true} />);
  button = container.querySelector('div');
  expect(button).toHaveStyle({ backgroundColor: '#909090' });
});

it('should interpolate cursor position from start to end', () => {
  mockUseCurrentFrame.mockReturnValue(15);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<SubscribeButtonAnimation />);
  const cursor = container.querySelector('[style*="position: absolute"]');
  expect(cursor).toBeInTheDocument();
  const top = cursor?.style.top;
  expect(top).toBeDefined();
});

it('should switch from arrow to hand cursor at frame 17', () => {
  mockUseCurrentFrame.mockReturnValue(16);
  const { container, rerender } = render(<SubscribeButtonAnimation />);
  expect(container.innerHTML).toContain('ArrowCursor');

  mockUseCurrentFrame.mockReturnValue(17);
  rerender(<SubscribeButtonAnimation />);
  expect(container.innerHTML).toContain('HandCursor');
});

it('should apply click offset during click frames 45-50', () => {
  mockUseCurrentFrame.mockReturnValue(47);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<SubscribeButtonAnimation />);
  const cursor = container.querySelector('[style*="z-index: 100"]');
  const top = cursor?.style.top;
  expect(top).toMatch(/\d+px/);
});

it('should generate exactly 12 stars when clicked', () => {
  mockUseCurrentFrame.mockReturnValue(50);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<SubscribeButtonAnimation />);
  const stars = container.querySelectorAll('[style*="position: absolute"]');
  // Filter out cursor element
  const starElements = Array.from(stars).filter(el => !el.style.zIndex);
  expect(starElements.length).toBeGreaterThanOrEqual(0);
});

it('should not render stars before click frame', () => {
  mockUseCurrentFrame.mockReturnValue(44);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container } = render(<SubscribeButtonAnimation />);
  const starSvgs = container.querySelectorAll('svg[viewBox="0 0 24 24"]');
  expect(starSvgs.length).toBeLessThanOrEqual(2); // Only button and cursor SVGs
});

it('should respect TIMING.CLICK_FRAME for button click state', () => {
  mockUseCurrentFrame.mockReturnValue(44);
  mockUseVideoConfig.mockReturnValue({ fps: 30, width: 1920, height: 1080 });
  const { container, rerender } = render(<SubscribeButtonAnimation />);
  let button = container.querySelector('[style*="#FF0000"]');
  expect(button).toBeInTheDocument();

  mockUseCurrentFrame.mockReturnValue(45);
  rerender(<SubscribeButtonAnimation />);
  button = container.querySelector('[style*="#909090"]');
  expect(button).toBeInTheDocument();
});

