const useCursorAnimation = (frame: number, fps: number, width: number, height: number, centerX: number, centerY: number) => {
  const startX = width / 2;
  const startY = height + 111;
  const endX = centerX + 74;
  const endY = centerY + 37;

  const moveProgress = spring({
    fps,
    frame,
    config: { damping: 50, stiffness: 100 },
    durationInFrames: TIMING.CURSOR_MOVE_END,
  });

  const clampedProgress = Math.min(moveProgress, 1);
  const interpolateConfig = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  return {
    x: interpolate(clampedProgress, [0, 1], [startX, endX], interpolateConfig),
    y: interpolate(clampedProgress, [0, 1], [startY, endY], interpolateConfig),
  };
};

const { x: cursorX, y: cursorY } = useCursorAnimation(frame, fps, width, height, buttonCenterX, buttonCenterY);

