const getButtonScale = (clicked: boolean, frame: number, fps: number): number => {
  if (!clicked || frame < TIMING.CLICK_FRAME) return 1;

  const clickProgress = spring({
    fps,
    frame: frame - TIMING.CLICK_FRAME,
    config: { damping: 15, stiffness: 300 },
  });

  return interpolate(clickProgress, [0, 1], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
};

